  ('Mychashi', 'تحويل عبر ماي كاشي', 'حوّلي المبلغ عبر تطبيق ماي كاشي ثم أدخلي رقم العملية وصورة الإيصال.', true, true, 20)
ON CONFLICT (code) DO UPDATE SET
  name_ar = EXCLUDED.name_ar,
  description_ar = EXCLUDED.description_ar,
