-- >>>>> Migration: 20260923000000_auth_providers.sql <<<<<

-- 0014 Multi-provider authentication (Google, Apple, phone OTP) alongside email+password.
-- Decisions (grilled 2026-09-23):
-- - Social/phone sign-in is for Customers only; Drivers and Admins stay on email+password.
-- - Ordering requires a *verified contact* (email OR phone), not specifically a verified email.
-- - Phone is mirrored onto profiles in E.164 so staff and the Admin Portal can read it without
--   reaching into the auth schema.
-- - Which methods are live is a server-side setting, never a build-time flag: a shipped mobile build
--   cannot be re-flagged without another store review cycle.

-- Phone normalisation ----------------------------------------------------------
-- Sudanese numbers arrive as 09xxxxxxxx locally, 249xxxxxxxxx from some keyboards, +249xxxxxxxxx from
-- others. Without one canonical form the unique index below is meaningless.
CREATE OR REPLACE FUNCTION public.normalize_sd_phone(p_phone text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_digits text;
BEGIN
  IF p_phone IS NULL THEN RETURN NULL; END IF;
  v_digits := regexp_replace(p_phone, '[^0-9]', '', 'g');
  v_digits := regexp_replace(v_digits, '^00249', '');
  v_digits := regexp_replace(v_digits, '^249', '');
  v_digits := regexp_replace(v_digits, '^0', '');
  -- Sudanese mobile national numbers are 9 digits starting 1 or 9.
  IF v_digits ~ '^[19][0-9]{8}$' THEN RETURN '+249' || v_digits; END IF;
  RETURN NULL;
END;
$fn$;

ALTER FUNCTION public.normalize_sd_phone(text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.normalize_sd_phone(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.normalize_sd_phone(text) TO anon, authenticated, service_role;

-- profiles ---------------------------------------------------------------------
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS phone text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS phone_confirmed_at timestamp with time zone;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS full_name text;
ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS signup_method text;

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_signup_method_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_signup_method_check
  CHECK (signup_method IS NULL OR signup_method IN ('password', 'google', 'apple', 'phone'));

ALTER TABLE public.profiles DROP CONSTRAINT IF EXISTS profiles_phone_e164_check;
ALTER TABLE public.profiles ADD CONSTRAINT profiles_phone_e164_check
  CHECK (phone IS NULL OR phone ~ '^\+[1-9][0-9]{7,14}$');

-- A verified phone is an identity, so it belongs to exactly one account. Unverified copies
-- (backfilled from checkout history) are deliberately not unique: family members really did share a
-- number at checkout before this existed.
CREATE UNIQUE INDEX IF NOT EXISTS profiles_phone_confirmed_unique_idx
  ON public.profiles (phone) WHERE phone IS NOT NULL AND phone_confirmed_at IS NOT NULL;
CREATE INDEX IF NOT EXISTS profiles_phone_idx ON public.profiles (phone) WHERE phone IS NOT NULL;

-- New users --------------------------------------------------------------------
-- Was: inserted id/email/role only, discarding the full name and phone the signup form collects.
CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $fn$
DECLARE
  v_provider text := COALESCE(new.raw_app_meta_data->>'provider', 'email');
  v_method text;
  v_phone text;
  v_name text;
BEGIN
  v_method := CASE v_provider
    WHEN 'google' THEN 'google'
    WHEN 'apple' THEN 'apple'
    WHEN 'phone' THEN 'phone'
    ELSE 'password'
  END;

  -- auth.users.phone is set by phone OTP sign-up; the signup form passes phone in user metadata.
  v_phone := public.normalize_sd_phone(COALESCE(new.phone, new.raw_user_meta_data->>'phone'));

  -- Apple returns the name on the FIRST authorisation only; Google sends it every time.
  v_name := NULLIF(trim(COALESCE(
    new.raw_user_meta_data->>'full_name',
    new.raw_user_meta_data->>'name',
    CONCAT_WS(' ', new.raw_user_meta_data->>'given_name', new.raw_user_meta_data->>'family_name')
  )), '');

  INSERT INTO public.profiles (id, email, role, phone, phone_confirmed_at, full_name, signup_method)
  VALUES (
    new.id,
    new.email,
    'customer',
    v_phone,
    CASE WHEN new.phone_confirmed_at IS NOT NULL AND v_phone IS NOT NULL THEN new.phone_confirmed_at END,
    v_name,
    v_method
  )
  ON CONFLICT (id) DO UPDATE SET
    email = COALESCE(public.profiles.email, EXCLUDED.email),
    phone = COALESCE(public.profiles.phone, EXCLUDED.phone),
    full_name = COALESCE(public.profiles.full_name, EXCLUDED.full_name);
  RETURN new;
END;
$fn$;

ALTER FUNCTION public.handle_new_user() OWNER TO postgres;

-- Keep profiles in step when auth.users gains a verified contact later: a phone added to an existing
-- password account, or an Apple relay address confirmed.
CREATE OR REPLACE FUNCTION public.sync_profile_contact() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $fn$
DECLARE
  v_phone text := public.normalize_sd_phone(new.phone);
BEGIN
  UPDATE public.profiles p SET
    email = COALESCE(new.email, p.email),
    phone = COALESCE(v_phone, p.phone),
    phone_confirmed_at = CASE
      WHEN new.phone_confirmed_at IS NOT NULL AND v_phone IS NOT NULL THEN new.phone_confirmed_at
      ELSE p.phone_confirmed_at
    END,
    full_name = COALESCE(p.full_name, NULLIF(trim(COALESCE(
      new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name')), ''))
  WHERE p.id = new.id;
  RETURN new;
END;
$fn$;

ALTER FUNCTION public.sync_profile_contact() OWNER TO postgres;

DROP TRIGGER IF EXISTS on_auth_user_contact_updated ON auth.users;
CREATE TRIGGER on_auth_user_contact_updated
  AFTER UPDATE OF email, phone, email_confirmed_at, phone_confirmed_at, raw_user_meta_data ON auth.users
  FOR EACH ROW EXECUTE FUNCTION public.sync_profile_contact();

-- Customers only ---------------------------------------------------------------
-- A Driver who taps "Continue with Google" would otherwise land a second, customer-role account with
-- their work email, none of their deliveries in it, and a support call for you.
CREATE OR REPLACE FUNCTION public.enforce_customer_only_social_identity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $fn$
DECLARE
  v_role text;
BEGIN
  IF new.provider IN ('email', 'phone') THEN RETURN new; END IF;
  SELECT role INTO v_role FROM public.profiles WHERE id = new.user_id;
  IF v_role IS NOT NULL AND v_role <> 'customer' THEN
    RAISE EXCEPTION 'staff_social_login_not_allowed'
      USING HINT = 'Staff and driver accounts sign in with email and password.';
  END IF;
  RETURN new;
END;
$fn$;

ALTER FUNCTION public.enforce_customer_only_social_identity() OWNER TO postgres;

DROP TRIGGER IF EXISTS on_auth_identity_created ON auth.identities;
CREATE TRIGGER on_auth_identity_created
  BEFORE INSERT ON auth.identities
  FOR EACH ROW EXECUTE FUNCTION public.enforce_customer_only_social_identity();

-- Verified contact -------------------------------------------------------------
-- Replaces "verified email" as the gate on ordering: a phone-only customer has no email to confirm.
CREATE OR REPLACE FUNCTION public.has_verified_contact(p_user_id uuid DEFAULT NULL) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $fn$
  SELECT EXISTS (
    SELECT 1 FROM auth.users u
    WHERE u.id = COALESCE(p_user_id, (SELECT auth.uid()))
      AND (u.email_confirmed_at IS NOT NULL OR u.phone_confirmed_at IS NOT NULL)
  );
$fn$;

ALTER FUNCTION public.has_verified_contact(uuid) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.has_verified_contact(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.has_verified_contact(uuid) TO authenticated, service_role;

-- Server-side method flags -----------------------------------------------------
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS auth_password_enabled boolean NOT NULL DEFAULT true;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS auth_google_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS auth_apple_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS auth_phone_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS auth_captcha_enabled boolean NOT NULL DEFAULT false;

-- app_settings is admin-only under RLS, but the login screen has to read these while signed out.
CREATE OR REPLACE FUNCTION public.get_auth_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
  SELECT jsonb_build_object(
    'password', s.auth_password_enabled,
    'google', s.auth_google_enabled,
    'apple', s.auth_apple_enabled,
    'phone', s.auth_phone_enabled,
    'captcha', s.auth_captcha_enabled
  )
  FROM public.app_settings s WHERE s.id;
$fn$;

ALTER FUNCTION public.get_auth_settings() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.get_auth_settings() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_auth_settings() TO anon, authenticated, service_role;

-- Backfill ---------------------------------------------------------------------
-- Existing accounts kept name and phone in auth user metadata only; checkout addresses are the second
-- source. Neither is verified, so neither sets phone_confirmed_at.
UPDATE public.profiles p SET
  full_name = COALESCE(p.full_name, NULLIF(trim(COALESCE(u.raw_user_meta_data->>'full_name', u.raw_user_meta_data->>'name')), '')),
  phone = COALESCE(p.phone, public.normalize_sd_phone(COALESCE(u.phone, u.raw_user_meta_data->>'phone'))),
  phone_confirmed_at = COALESCE(
    p.phone_confirmed_at,
    CASE WHEN public.normalize_sd_phone(u.phone) IS NOT NULL THEN u.phone_confirmed_at END),
  signup_method = COALESCE(p.signup_method, CASE COALESCE(u.raw_app_meta_data->>'provider', 'email')
    WHEN 'google' THEN 'google' WHEN 'apple' THEN 'apple' WHEN 'phone' THEN 'phone' ELSE 'password' END)
FROM auth.users u
WHERE u.id = p.id;

-- Second source: the phone the customer typed at their most recent checkout. Unverified, so it fills
-- profiles.phone for staff to call, but never phone_confirmed_at and never the unique index.
UPDATE public.profiles p SET phone = src.phone
FROM (
  SELECT DISTINCT ON (o.customer_id)
    o.customer_id,
    public.normalize_sd_phone(o.phone) AS phone
  FROM public.orders o
  WHERE o.customer_id IS NOT NULL AND public.normalize_sd_phone(o.phone) IS NOT NULL
  ORDER BY o.customer_id, o.created_at DESC
) src
WHERE src.customer_id = p.id AND p.phone IS NULL;


-- >>>>> Migration: 20260924000000_push_fcm.sql <<<<<

-- 0015 Push notifications: add FCM/APNs alongside Expo.
--
-- The backend was built for an Expo wrapper that no longer exists: customer_push_tokens.expo_push_token
-- is NOT NULL, unique, and constrained to `ExponentPushToken[...]`, so a Capacitor token could not
-- even be stored. The Capacitor apps produce FCM registration tokens (Firebase delivers to APNs for
-- iOS), so the table has to hold both shapes.
--
-- Nothing Expo is removed here. Old rows keep working, register_customer_push_token() keeps its exact
-- signature and behaviour, and the dispatcher routes per row. Expo comes out only once FCM is verified
-- on real handsets.

-- Tokens -----------------------------------------------------------------------
ALTER TABLE public.customer_push_tokens ADD COLUMN IF NOT EXISTS provider text NOT NULL DEFAULT 'expo';
ALTER TABLE public.customer_push_tokens ADD COLUMN IF NOT EXISTS push_token text;

ALTER TABLE public.customer_push_tokens DROP CONSTRAINT IF EXISTS customer_push_tokens_provider_check;
ALTER TABLE public.customer_push_tokens ADD CONSTRAINT customer_push_tokens_provider_check
  CHECK (provider IN ('expo', 'fcm'));

-- Existing rows are all Expo; copy them into the generic column so the dispatcher has one place to
-- read from regardless of provider.
UPDATE public.customer_push_tokens SET push_token = expo_push_token WHERE push_token IS NULL;

-- expo_push_token has to become nullable for FCM rows to exist at all. The regex that used to live on
-- the column moves into the row-level check below, where it only applies to Expo rows.
ALTER TABLE public.customer_push_tokens ALTER COLUMN expo_push_token DROP NOT NULL;

ALTER TABLE public.customer_push_tokens DROP CONSTRAINT IF EXISTS customer_push_tokens_token_shape_check;
ALTER TABLE public.customer_push_tokens ADD CONSTRAINT customer_push_tokens_token_shape_check
  CHECK (
    push_token IS NOT NULL AND length(push_token) > 0
    AND (
      (provider = 'expo' AND expo_push_token IS NOT NULL
        AND expo_push_token ~ '^ExponentPushToken\[[^\]]+\]$|^ExpoPushToken\[[^\]]+\]$'
        AND push_token = expo_push_token)
      OR (provider = 'fcm' AND expo_push_token IS NULL)
    )
  );

-- One device, one row, whichever provider it speaks. The old unique index on expo_push_token stays
-- for Expo rows; this covers FCM too.
CREATE UNIQUE INDEX IF NOT EXISTS customer_push_tokens_push_token_key
  ON public.customer_push_tokens (push_token);

-- Registration -----------------------------------------------------------------
-- New name, provider-aware. register_customer_push_token() is untouched and still serves any client
-- that has not been updated.
CREATE OR REPLACE FUNCTION public.register_push_token(
  p_token text,
  p_provider text,
  p_platform text,
  p_device_name text DEFAULT NULL
) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_customer_id uuid := (SELECT auth.uid());
  v_token_id uuid;
  v_expo text;
BEGIN
  IF v_customer_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  IF p_platform NOT IN ('ios', 'android') THEN RAISE EXCEPTION 'Unsupported device platform'; END IF;
  IF p_provider NOT IN ('expo', 'fcm') THEN RAISE EXCEPTION 'Unsupported push provider'; END IF;
  IF p_token IS NULL OR length(trim(p_token)) = 0 THEN RAISE EXCEPTION 'Invalid push token'; END IF;

  IF p_provider = 'expo' THEN
    IF p_token !~ '^ExponentPushToken\[[^\]]+\]$|^ExpoPushToken\[[^\]]+\]$' THEN
      RAISE EXCEPTION 'Invalid Expo push token';
    END IF;
    v_expo := p_token;
  END IF;

  INSERT INTO public.customer_push_tokens AS t
    (customer_id, provider, push_token, expo_push_token, platform, device_name, is_active, invalidated_at, last_registered_at)
  VALUES
    (v_customer_id, p_provider, trim(p_token), v_expo, p_platform, NULLIF(trim(p_device_name), ''), true, NULL, timezone('utc', now()))
  ON CONFLICT (push_token) DO UPDATE SET
    -- A shared or resold handset can present the same token under a new account.
    customer_id = EXCLUDED.customer_id,
    provider = EXCLUDED.provider,
    expo_push_token = EXCLUDED.expo_push_token,
    platform = EXCLUDED.platform,
    device_name = EXCLUDED.device_name,
    is_active = true,
    invalidated_at = NULL,
    last_registered_at = timezone('utc', now())
  RETURNING t.id INTO v_token_id;

  RETURN v_token_id;
END;
$fn$;

ALTER FUNCTION public.register_push_token(text, text, text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.register_push_token(text, text, text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.register_push_token(text, text, text, text) TO authenticated, service_role;

-- Signing out on a shared device must stop that device receiving another customer's order updates.
CREATE OR REPLACE FUNCTION public.deactivate_push_token(p_token text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_customer_id uuid := (SELECT auth.uid());
  v_count integer;
BEGIN
  IF v_customer_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;
  UPDATE public.customer_push_tokens
     SET is_active = false, invalidated_at = timezone('utc', now())
   WHERE push_token = trim(p_token) AND customer_id = v_customer_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count > 0;
END;
$fn$;

ALTER FUNCTION public.deactivate_push_token(text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.deactivate_push_token(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.deactivate_push_token(text) TO authenticated, service_role;

-- Delivery log -----------------------------------------------------------------
-- expo_ticket_id stays for the Expo rows already logged; new rows record which transport ran and the
-- id that transport returned, so a failure can be traced to the right dashboard.
ALTER TABLE public.push_notification_deliveries ADD COLUMN IF NOT EXISTS provider text;
ALTER TABLE public.push_notification_deliveries ADD COLUMN IF NOT EXISTS provider_message_id text;

ALTER TABLE public.push_notification_deliveries DROP CONSTRAINT IF EXISTS push_notification_deliveries_provider_check;
ALTER TABLE public.push_notification_deliveries ADD CONSTRAINT push_notification_deliveries_provider_check
  CHECK (provider IS NULL OR provider IN ('expo', 'fcm'));

UPDATE public.push_notification_deliveries SET provider = 'expo' WHERE provider IS NULL;

-- Customers may read their own device list (Settings shows registered devices); the delivery log stays
-- admin-only, as it was.
DROP POLICY IF EXISTS "Customers view own push tokens" ON public.customer_push_tokens;
CREATE POLICY "Customers view own push tokens" ON public.customer_push_tokens
  FOR SELECT TO authenticated USING (customer_id = (SELECT auth.uid()) OR public.is_admin());

GRANT SELECT ON TABLE public.customer_push_tokens TO authenticated;


-- >>>>> Migration: 20260924000100_account_deletion.sql <<<<<

-- 0016 In-app account deletion.
--
-- Apple App Review Guideline 5.1.1(v) requires any app that creates accounts to let customers delete
-- them *inside the app*. A request form that emails staff is rejected. This is therefore a hard store
-- blocker, not a nicety.
--
-- It is a soft, anonymising delete: personal data goes, the financial record stays. Orders are
-- accounting records — deleting the rows would leave the books unable to explain their own totals —
-- so each order keeps its number, items, amounts and dates while losing the name, phone, address and
-- notes that identify a person. Behavioural data (favourites, restock alerts, AI usage) is deleted
-- outright; it has no accounting value.
--
-- The customer cannot sign in afterwards: sessions are destroyed, social identities unlinked, the
-- login address replaced with a tombstone, and the auth user banned.

CREATE TABLE IF NOT EXISTS public.account_deletions (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL PRIMARY KEY,
    customer_id uuid NOT NULL,
    -- Kept deliberately: staff need to answer "what happened to this order's customer?" during a
    -- payment dispute, without holding the identity itself.
    orders_anonymised integer NOT NULL DEFAULT 0,
    proofs_removed integer NOT NULL DEFAULT 0,
    requested_at timestamp with time zone NOT NULL DEFAULT timezone('utc', now())
);

ALTER TABLE public.account_deletions OWNER TO postgres;
ALTER TABLE public.account_deletions ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins view account deletions" ON public.account_deletions
  FOR SELECT TO authenticated USING (public.is_admin());
GRANT SELECT ON TABLE public.account_deletions TO authenticated;
GRANT ALL ON TABLE public.account_deletions TO service_role;

ALTER TABLE public.profiles ADD COLUMN IF NOT EXISTS deleted_at timestamp with time zone;

-- What the customer is told before they confirm. Read from the app so the warning cannot drift from
-- what the function actually does.
CREATE OR REPLACE FUNCTION public.account_deletion_preview() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
  SELECT jsonb_build_object(
    'orders', (SELECT count(*) FROM public.orders o WHERE o.customer_id = (SELECT auth.uid())),
    'active_orders', (SELECT count(*) FROM public.orders o
                       WHERE o.customer_id = (SELECT auth.uid())
                         AND o.status NOT IN ('delivered', 'cancelled')),
    'reviews', (SELECT count(*) FROM public.reviews r WHERE r.user_id = (SELECT auth.uid())),
    'beauty_points', (SELECT COALESCE(p.beauty_points, 0) FROM public.profiles p WHERE p.id = (SELECT auth.uid()))
  );
$fn$;

ALTER FUNCTION public.account_deletion_preview() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.account_deletion_preview() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.account_deletion_preview() TO authenticated, service_role;

CREATE OR REPLACE FUNCTION public.delete_my_account() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $fn$
DECLARE
  v_customer_id uuid := (SELECT auth.uid());
  v_role text;
  v_active integer;
  v_orders integer := 0;
  v_proofs integer := 0;
  v_tombstone text;
BEGIN
  IF v_customer_id IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF;

  SELECT role INTO v_role FROM public.profiles WHERE id = v_customer_id;
  -- Staff and Drivers are payroll records with deliveries attached; an admin removes those, not a
  -- self-service button.
  IF v_role IS DISTINCT FROM 'customer' THEN
    RAISE EXCEPTION 'staff_account_deletion_not_allowed'
      USING HINT = 'Staff and driver accounts are removed by an administrator.';
  END IF;

  -- An order still being prepared or delivered needs the name and phone it is being delivered to.
  SELECT count(*) INTO v_active FROM public.orders
   WHERE customer_id = v_customer_id AND status NOT IN ('delivered', 'cancelled');
  IF v_active > 0 THEN
    RAISE EXCEPTION 'active_orders_exist'
      USING HINT = 'Wait until in-flight orders are delivered or cancelled.';
  END IF;

  v_tombstone := 'deleted-' || replace(v_customer_id::text, '-', '') || '@deleted.invalid';

  -- Orders keep their money and lose their person.
  UPDATE public.orders SET
    customer_name = 'حساب محذوف',
    phone = NULL,
    shipping_address = NULL,
    notes = NULL
  WHERE customer_id = v_customer_id;
  GET DIAGNOSTICS v_orders = ROW_COUNT;

  -- Payment proofs are photographs of bank transfers: the single most sensitive thing stored. The
  -- amount and reference stay for reconciliation; the image goes.
  DELETE FROM storage.objects
   WHERE bucket_id = 'payment-proofs'
     AND name IN (SELECT proof_path FROM public.payment_proofs
                   WHERE customer_id = v_customer_id AND proof_path IS NOT NULL);
  GET DIAGNOSTICS v_proofs = ROW_COUNT;
  UPDATE public.payment_proofs SET proof_path = NULL WHERE customer_id = v_customer_id;

  -- Reviews are product content other customers rely on; the rating and text stay, the author does not.
  UPDATE public.reviews SET user_name = 'حساب محذوف' WHERE user_id = v_customer_id;

  -- Nothing further should ever be sent to this person.
  DELETE FROM public.notification_queue WHERE customer_id = v_customer_id AND status = 'pending';
  UPDATE public.notification_queue SET recipient_phone = NULL WHERE customer_id = v_customer_id;
  UPDATE public.customer_push_tokens
     SET is_active = false, invalidated_at = timezone('utc', now())
   WHERE customer_id = v_customer_id;
  DELETE FROM public.customer_notifications WHERE customer_id = v_customer_id;

  -- Behavioural data: no accounting value, so it is deleted rather than anonymised.
  DELETE FROM public.customer_favorites WHERE customer_id = v_customer_id;
  DELETE FROM public.restock_subscriptions WHERE customer_id = v_customer_id;
  DELETE FROM public.ai_request_limits WHERE customer_id = v_customer_id;
  DELETE FROM public.checkout_idempotency WHERE customer_id = v_customer_id;

  UPDATE public.profiles SET
    email = NULL,
    phone = NULL,
    phone_confirmed_at = NULL,
    full_name = NULL,
    referral_code = NULL,
    beauty_points = 0,
    deleted_at = timezone('utc', now())
  WHERE id = v_customer_id;

  INSERT INTO public.account_deletions (customer_id, orders_anonymised, proofs_removed)
  VALUES (v_customer_id, v_orders, v_proofs);

  -- Sign-in must stop immediately and permanently. Unlinking the social identities means a later
  -- "Continue with Google" creates a clean new account rather than resurrecting this one.
  DELETE FROM auth.sessions WHERE user_id = v_customer_id;
  DELETE FROM auth.refresh_tokens WHERE user_id = v_customer_id::text;
  DELETE FROM auth.identities WHERE user_id = v_customer_id;
  UPDATE auth.users SET
    email = v_tombstone,
    phone = NULL,
    raw_user_meta_data = '{}'::jsonb,
    -- A concrete far-future timestamp rather than 'infinity': GoTrue reads this column and its Go
    -- time handling has no equivalent for an infinite Postgres timestamp.
    banned_until = timezone('utc', now()) + interval '100 years'
  WHERE id = v_customer_id;

  RETURN jsonb_build_object('orders_anonymised', v_orders, 'proofs_removed', v_proofs);
END;
$fn$;

ALTER FUNCTION public.delete_my_account() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.delete_my_account() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.delete_my_account() TO authenticated;

-- A deleted profile must not be resurrected by the sign-up trigger's ON CONFLICT branch.
CREATE INDEX IF NOT EXISTS profiles_deleted_at_idx ON public.profiles (deleted_at) WHERE deleted_at IS NOT NULL;


-- >>>>> Migration: 20260924000200_otp_delivery.sql <<<<<

-- 0017 Phone OTP delivery: rate limiting, channel settings, and a delivery log.
--
-- Every OTP costs real money (SMS to Sudan is around $0.47 a message at list price), so an unmetered
-- endpoint is a way to spend someone else's budget. Limits are enforced in SQL rather than in the Edge
-- Function because only the database can count attempts atomically across concurrent requests.
--
-- No production SMS provider is committed. The channel is configuration, and the dispatcher reads these
-- settings at send time, so switching provider or channel never touches the auth architecture.

-- Attempt ledger ---------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.otp_request_attempts (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL PRIMARY KEY,
    phone text NOT NULL,
    -- Nullable: the hook does not always see a client IP, and a missing IP must not block a real customer.
    ip_address text,
    created_at timestamp with time zone NOT NULL DEFAULT timezone('utc', now())
);

ALTER TABLE public.otp_request_attempts OWNER TO postgres;
ALTER TABLE public.otp_request_attempts ENABLE ROW LEVEL SECURITY;
CREATE INDEX IF NOT EXISTS otp_request_attempts_phone_idx ON public.otp_request_attempts (phone, created_at DESC);
CREATE INDEX IF NOT EXISTS otp_request_attempts_ip_idx ON public.otp_request_attempts (ip_address, created_at DESC) WHERE ip_address IS NOT NULL;
GRANT ALL ON TABLE public.otp_request_attempts TO service_role;

-- Delivery log -----------------------------------------------------------------
-- "The code never arrived" is unanswerable without this. Admin-only: it holds phone numbers.
CREATE TABLE IF NOT EXISTS public.otp_delivery_log (
    id uuid DEFAULT extensions.uuid_generate_v4() NOT NULL PRIMARY KEY,
    phone text NOT NULL,
    channel text NOT NULL,
    provider text,
    status text NOT NULL,
    provider_message_id text,
    error_message text,
    -- Which attempt this was for the number, so a support conversation can be reconstructed.
    attempt integer,
    created_at timestamp with time zone NOT NULL DEFAULT timezone('utc', now()),
    CONSTRAINT otp_delivery_log_channel_check CHECK (channel IN ('whatsapp', 'sms')),
    CONSTRAINT otp_delivery_log_status_check CHECK (status IN ('sent', 'failed', 'blocked'))
);

ALTER TABLE public.otp_delivery_log OWNER TO postgres;
ALTER TABLE public.otp_delivery_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Admins view otp delivery log" ON public.otp_delivery_log
  FOR SELECT TO authenticated USING (public.is_admin());
CREATE INDEX IF NOT EXISTS otp_delivery_log_created_idx ON public.otp_delivery_log (created_at DESC);
CREATE INDEX IF NOT EXISTS otp_delivery_log_phone_idx ON public.otp_delivery_log (phone, created_at DESC);
GRANT SELECT ON TABLE public.otp_delivery_log TO authenticated;
GRANT ALL ON TABLE public.otp_delivery_log TO service_role;

-- Channel settings -------------------------------------------------------------
-- WhatsApp first, SMS as fallback: WhatsApp costs a fraction of SMS, but Sudan has frequent nationwide
-- internet shutdowns and SMS survives a data-only outage. Both switchable without a release.
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS otp_whatsapp_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS otp_sms_enabled boolean NOT NULL DEFAULT false;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS otp_primary_channel text NOT NULL DEFAULT 'whatsapp';
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS otp_cooldown_seconds integer NOT NULL DEFAULT 60;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS otp_max_per_phone_hour integer NOT NULL DEFAULT 5;
ALTER TABLE public.app_settings ADD COLUMN IF NOT EXISTS otp_max_per_ip_hour integer NOT NULL DEFAULT 20;

ALTER TABLE public.app_settings DROP CONSTRAINT IF EXISTS app_settings_otp_primary_channel_check;
ALTER TABLE public.app_settings ADD CONSTRAINT app_settings_otp_primary_channel_check
  CHECK (otp_primary_channel IN ('whatsapp', 'sms'));

-- Read by the delivery hook (service role only: these are operational, not public like the auth flags).
CREATE OR REPLACE FUNCTION public.get_otp_settings() RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
  SELECT jsonb_build_object(
    'whatsapp_enabled', s.otp_whatsapp_enabled,
    'sms_enabled', s.otp_sms_enabled,
    'primary_channel', s.otp_primary_channel,
    'cooldown_seconds', s.otp_cooldown_seconds,
    'max_per_phone_hour', s.otp_max_per_phone_hour,
    'max_per_ip_hour', s.otp_max_per_ip_hour
  )
  FROM public.app_settings s WHERE s.id;
$fn$;

ALTER FUNCTION public.get_otp_settings() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.get_otp_settings() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.get_otp_settings() TO service_role;

-- Rate limiting ----------------------------------------------------------------
-- Records the attempt and decides in the same statement, so two concurrent requests cannot both pass a
-- limit that only allows one. Returns the reason so the app can say something true in Arabic rather
-- than a generic failure.
CREATE OR REPLACE FUNCTION public.record_otp_attempt(p_phone text, p_ip text DEFAULT NULL)
RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_phone text := public.normalize_sd_phone(p_phone);
  v_settings jsonb;
  v_cooldown integer;
  v_max_phone integer;
  v_max_ip integer;
  v_last timestamp with time zone;
  v_phone_count integer;
  v_ip_count integer;
  v_wait integer;
BEGIN
  IF v_phone IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_phone', 'retry_after', 0, 'attempt', 0);
  END IF;

  SELECT public.get_otp_settings() INTO v_settings;
  v_cooldown := COALESCE((v_settings->>'cooldown_seconds')::integer, 60);
  v_max_phone := COALESCE((v_settings->>'max_per_phone_hour')::integer, 5);
  v_max_ip := COALESCE((v_settings->>'max_per_ip_hour')::integer, 20);

  -- Serialise per number: two taps on "resend" must not both get through the cooldown.
  PERFORM pg_advisory_xact_lock(hashtext('otp:' || v_phone));

  SELECT max(created_at) INTO v_last FROM public.otp_request_attempts WHERE phone = v_phone;
  IF v_last IS NOT NULL THEN
    v_wait := v_cooldown - floor(extract(epoch FROM (timezone('utc', now()) - v_last)))::integer;
    IF v_wait > 0 THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'cooldown', 'retry_after', v_wait, 'attempt', 0);
    END IF;
  END IF;

  SELECT count(*) INTO v_phone_count FROM public.otp_request_attempts
   WHERE phone = v_phone AND created_at > timezone('utc', now()) - interval '1 hour';
  IF v_phone_count >= v_max_phone THEN
    RETURN jsonb_build_object('allowed', false, 'reason', 'phone_quota', 'retry_after', 3600, 'attempt', v_phone_count);
  END IF;

  IF p_ip IS NOT NULL THEN
    SELECT count(*) INTO v_ip_count FROM public.otp_request_attempts
     WHERE ip_address = p_ip AND created_at > timezone('utc', now()) - interval '1 hour';
    IF v_ip_count >= v_max_ip THEN
      RETURN jsonb_build_object('allowed', false, 'reason', 'ip_quota', 'retry_after', 3600, 'attempt', v_phone_count);
    END IF;
  END IF;

  INSERT INTO public.otp_request_attempts (phone, ip_address) VALUES (v_phone, p_ip);

  RETURN jsonb_build_object('allowed', true, 'reason', 'ok', 'retry_after', 0, 'attempt', v_phone_count + 1);
END;
$fn$;

ALTER FUNCTION public.record_otp_attempt(text, text) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.record_otp_attempt(text, text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.record_otp_attempt(text, text) TO service_role;

CREATE OR REPLACE FUNCTION public.log_otp_delivery(
  p_phone text,
  p_channel text,
  p_provider text,
  p_status text,
  p_provider_message_id text DEFAULT NULL,
  p_error text DEFAULT NULL,
  p_attempt integer DEFAULT NULL
) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_id uuid;
BEGIN
  INSERT INTO public.otp_delivery_log (phone, channel, provider, status, provider_message_id, error_message, attempt)
  VALUES (COALESCE(public.normalize_sd_phone(p_phone), p_phone), p_channel, p_provider, p_status, p_provider_message_id, p_error, p_attempt)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$fn$;

ALTER FUNCTION public.log_otp_delivery(text, text, text, text, text, text, integer) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.log_otp_delivery(text, text, text, text, text, text, integer) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.log_otp_delivery(text, text, text, text, text, text, integer) TO service_role;

-- Attempt rows are rate-limiting state, not history: anything older than a day is dead weight, and it
-- is phone numbers we have no reason to keep.
CREATE OR REPLACE FUNCTION public.prune_otp_attempts() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_removed integer;
BEGIN
  DELETE FROM public.otp_request_attempts WHERE created_at < timezone('utc', now()) - interval '1 day';
  GET DIAGNOSTICS v_removed = ROW_COUNT;
  RETURN v_removed;
END;
$fn$;

ALTER FUNCTION public.prune_otp_attempts() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.prune_otp_attempts() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.prune_otp_attempts() TO service_role;

-- cron.schedule replaces a job of the same name, so re-running this migration is safe.
-- To undo: SELECT cron.unschedule('prune-otp-attempts');
SELECT cron.schedule('prune-otp-attempts', '17 3 * * *', $$SELECT public.prune_otp_attempts();$$);


-- >>>>> Migration: 20260924000300_whatsapp_notifications.sql <<<<<

-- 0018 WhatsApp order confirmations for phone-only customers, and one place to see delivery failures.
--
-- Phone sign-in creates customers with no email address. The email pipeline sends order confirmations to
-- profiles.email, so those customers would silently hear nothing about an order they just paid for —
-- the hole phone sign-in opens, and the reason this exists.
--
-- Scope is deliberately one message: the order confirmation, matching exactly what email customers get.
-- Every additional template is its own Meta approval cycle in Arabic, and utility messages outside the
-- 24-hour window each cost money.
--
-- The email path is untouched. This is a second trigger rather than an edit to
-- queue_order_email_notification(), so a fault here cannot break the channel that already works.

CREATE OR REPLACE FUNCTION public.queue_order_whatsapp_notification() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_email text;
  v_phone text;
BEGIN
  SELECT p.email, p.phone INTO v_email, v_phone FROM public.profiles p WHERE p.id = NEW.customer_id;

  -- Only where email cannot reach them. A customer with an email already gets the confirmation there,
  -- and sending both would be two costs for one message.
  IF v_email IS NOT NULL AND length(trim(v_email)) > 0 THEN
    RETURN NEW;
  END IF;

  -- Fall back to the phone on the order itself: a guest-style checkout may carry a number the profile
  -- does not have yet.
  v_phone := COALESCE(public.normalize_sd_phone(v_phone), public.normalize_sd_phone(NEW.phone));
  IF v_phone IS NULL THEN
    RETURN NEW;
  END IF;

  INSERT INTO public.notification_queue (order_id, customer_id, channel, event_type, message, payload, recipient_phone)
  VALUES (
    NEW.id,
    NEW.customer_id,
    'whatsapp',
    'order_created',
    'تم استلام طلبك رقم ' || COALESCE(NEW.order_number, '') || ' بنجاح.',
    jsonb_build_object('audience', 'customer', 'order_number', NEW.order_number),
    v_phone
  );
  RETURN NEW;
END;
$fn$;

ALTER FUNCTION public.queue_order_whatsapp_notification() OWNER TO postgres;

DROP TRIGGER IF EXISTS orders_queue_whatsapp_notification ON public.orders;
CREATE TRIGGER orders_queue_whatsapp_notification
  AFTER INSERT ON public.orders
  FOR EACH ROW EXECUTE FUNCTION public.queue_order_whatsapp_notification();

CREATE INDEX IF NOT EXISTS notification_queue_pending_whatsapp_idx
  ON public.notification_queue (created_at) WHERE channel = 'whatsapp' AND status = 'pending';

-- Dispatcher -------------------------------------------------------------------
-- Mirrors dispatch_email_queue() exactly, including the vault-secret pattern and the "do nothing until
-- the secrets exist" posture, so the two pipelines behave the same way in an outage.
CREATE OR REPLACE FUNCTION public.dispatch_whatsapp_queue() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $fn$
DECLARE
  v_key text;
  v_url text;
BEGIN
  IF NOT EXISTS (SELECT 1 FROM public.notification_queue WHERE channel = 'whatsapp' AND status = 'pending' AND attempts < 5) THEN
    RETURN;
  END IF;
  SELECT decrypted_secret INTO v_key FROM vault.decrypted_secrets WHERE name = 'send_order_whatsapp_key' LIMIT 1;
  SELECT decrypted_secret INTO v_url FROM vault.decrypted_secrets WHERE name = 'send_order_whatsapp_url' LIMIT 1;
  IF v_key IS NULL OR v_url IS NULL THEN
    RETURN;
  END IF;
  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type', 'application/json', 'x-cron-key', v_key),
    body := '{}'::jsonb,
    timeout_milliseconds := 20000
  );
END;
$fn$;

ALTER FUNCTION public.dispatch_whatsapp_queue() OWNER TO postgres;
REVOKE ALL ON FUNCTION public.dispatch_whatsapp_queue() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.dispatch_whatsapp_queue() TO service_role;

SELECT cron.schedule('dispatch-whatsapp-queue', '* * * * *', $$SELECT public.dispatch_whatsapp_queue();$$);

-- Monitoring -------------------------------------------------------------------
-- Three pipelines fail in three different tables, and a customer who hears nothing does not know which
-- one broke. This is the single answer to "did our messages actually go out?", for the Admin Portal.
CREATE OR REPLACE FUNCTION public.admin_delivery_failures(p_hours integer DEFAULT 48, p_limit integer DEFAULT 200)
RETURNS TABLE (
  source text,
  channel text,
  status text,
  recipient text,
  reference text,
  error_message text,
  attempts integer,
  order_number text,
  created_at timestamp with time zone
)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required.'; END IF;

  RETURN QUERY
  -- Order notifications (email and WhatsApp) that did not go out.
  SELECT
    'notification_queue'::text,
    q.channel,
    q.status,
    COALESCE(q.recipient_phone, (SELECT p.email FROM public.profiles p WHERE p.id = q.customer_id)),
    q.provider_reference,
    q.error_message,
    q.attempts,
    (SELECT o.order_number FROM public.orders o WHERE o.id = q.order_id),
    q.created_at
  FROM public.notification_queue q
  WHERE q.status IN ('failed', 'cancelled')
    AND q.created_at > timezone('utc', now()) - make_interval(hours => p_hours)

  UNION ALL

  -- Login codes that were never delivered, or were refused by the rate limiter.
  SELECT
    'otp_delivery_log'::text,
    l.channel,
    l.status,
    l.phone,
    l.provider_message_id,
    l.error_message,
    l.attempt,
    NULL::text,
    l.created_at
  FROM public.otp_delivery_log l
  WHERE l.status IN ('failed', 'blocked')
    AND l.created_at > timezone('utc', now()) - make_interval(hours => p_hours)

  UNION ALL

  -- Push notifications rejected by Expo or FCM.
  SELECT
    'push_notification_deliveries'::text,
    COALESCE(d.provider, 'expo'),
    d.status,
    NULL::text,
    d.provider_message_id,
    d.error_message,
    NULL::integer,
    (SELECT o.order_number FROM public.orders o WHERE o.id = d.order_id),
    d.created_at
  FROM public.push_notification_deliveries d
  WHERE d.status = 'failed'
    AND d.created_at > timezone('utc', now()) - make_interval(hours => p_hours)

  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$fn$;

ALTER FUNCTION public.admin_delivery_failures(integer, integer) OWNER TO postgres;
REVOKE ALL ON FUNCTION public.admin_delivery_failures(integer, integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.admin_delivery_failures(integer, integer) TO authenticated, service_role;

-- Counts for the screen's header, so staff can see at a glance whether a channel is dead.
CREATE OR REPLACE FUNCTION public.admin_delivery_summary(p_hours integer DEFAULT 48)
RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $fn$
DECLARE
  v_since timestamp with time zone := timezone('utc', now()) - make_interval(hours => p_hours);
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Administrator access required.'; END IF;

  RETURN jsonb_build_object(
    'hours', p_hours,
    'email', (SELECT jsonb_build_object(
        'sent', count(*) FILTER (WHERE status = 'sent'),
        'pending', count(*) FILTER (WHERE status = 'pending'),
        'failed', count(*) FILTER (WHERE status IN ('failed', 'cancelled')))
      FROM public.notification_queue WHERE channel = 'email' AND created_at > v_since),
    'whatsapp', (SELECT jsonb_build_object(
        'sent', count(*) FILTER (WHERE status = 'sent'),
        'pending', count(*) FILTER (WHERE status = 'pending'),
        'failed', count(*) FILTER (WHERE status IN ('failed', 'cancelled')))
      FROM public.notification_queue WHERE channel = 'whatsapp' AND created_at > v_since),
    'otp', (SELECT jsonb_build_object(
        'sent', count(*) FILTER (WHERE status = 'sent'),
        'blocked', count(*) FILTER (WHERE status = 'blocked'),
        'failed', count(*) FILTER (WHERE status = 'failed'))
      FROM public.otp_delivery_log WHERE created_at > v_since),
    'push', (SELECT jsonb_build_object(
        'sent', count(*) FILTER (WHERE status = 'submitted'),
        'failed', count(*) FILTER (WHERE status = 'failed'))
      FROM public.push_notification_deliveries WHERE created_at > v_since)
  );
END;
$fn$;

