INSERT INTO public.orders_notes_eta_backup (order_id, notes)
SELECT o.id, o.notes FROM public.orders o
WHERE o.notes ~ '\[(الموعد المتوقع|تحديث):'
ON CONFLICT (order_id) DO NOTHING;

